        local floor = placed[1] and placed[1].r or -1
        local slotsFree = #placed < ((D.Plot and D.Plot.DefaultUnlockedSlots or 5) + (tonumber(d.BaseLevel) or 0))
        local better = slotsFree
        for _, it in pairs(d.Inventory or {}) do if type(it) == "table" and it.ItemType == "Treasure" and F.rank(it) > floor then better = true break end end
        if better then
            M.fire("PlaceBestLuck") S.placed += 1
            local t0 = os.clock()
            repeat task.wait(0.1) until F.invCount(M.data()) ~= n or os.clock() - t0 > 1
            if val("pl_mode", "Income") == "Income" then pcall(F.smartPlace) end
        end
    end
    if on("f_sell") then F.sell() end
    if on("f_lucky") and lucky > 0 then F.lucky() end
end
function F.sell()
    local d = M.data()
    if not d then return end
    local placed = F.placed(d)
    local floor = (on("f_place") and placed[1]) and placed[1].r or math.huge
    local list, sum = {}, 0
    for _, it in pairs(d.Inventory or {}) do
        if type(it) == "table" and it.ItemType == "Treasure" and not it.IsFavorite and it.UUID ~= d.EquippedPrimaryUUID and F.rank(it) <= floor then list[#list + 1] = it sum += F.value(it) end
    end
    if #list == 0 then return end
    M.fire("SellItems", list)
    S.sold += #list
    LOG("sold", #list, "for", M.fmt(sum))
end
function F.lucky()
    local d = M.data()
    for _, it in pairs(d and d.Inventory or {}) do
        if type(it) == "table" and it.ItemType == "LuckyBlock" and it.UUID then
            local t0 = os.clock()
            while lp:GetAttribute("OpeningInventoryBlock") ~= nil and os.clock() - t0 < 15 do task.wait(0.3) end
            local r = M.inv("OpenInventoryLuckyBlock", it.UUID)
            LOG("lucky block", type(r) == "table" and tostring(r.ok) or tostring(r))
            if type(r) == "table" and r.ok then M.fire("InventoryLuckyBlockFinished", it.UUID) end
            task.wait(1)
            t0 = os.clock()
            while lp:GetAttribute("OpeningInventoryBlock") ~= nil and os.clock() - t0 < 15 do task.wait(0.3) end
        end
    end
end
F.colAt = 0
function F.collect()
    if not on("f_collect") or M.busy or not M.free() or os.clock() - F.colAt < (tonumber(val("c_every", 30)) or 30) then return false end
    M.busy = true
    F.colAt = os.clock()
    local d = M.data()
    local plot = M.plot()
    if not (d and plot) then M.busy = false return false end
    local cps = lp:GetAttribute("CashPerSec") or 0
    local list = {}
    for fl, slots in pairs(d.Plot or {}) do
        for sl, info in pairs(slots) do
            if type(info) == "table" and (info.Stored or 0) > math.max(1, cps * 2) then
                local s = plot:FindFirstChild(fl) and plot[fl]:FindFirstChild("Slots") and plot[fl].Slots:FindFirstChild(sl)
                local pad = s and s:FindFirstChild("CollectTouch", true)
                if pad then list[#list + 1] = { pad = pad, fl = fl, sl = sl } end
            end
        end
    end
    if #list == 0 then M.busy = false return false end
    S.task = __T["Collecting cash"] S.taskAt = os.clock()
    local c0 = M.cash()
    pcall(function()
        for _, e in ipairs(list) do
            if not (RUNNING and M.free()) then break end
            local function left() local dd = M.data() local info = dd and dd.Plot[e.fl] and dd.Plot[e.fl][e.sl] return info and (info.Stored or 0) or 0 end
            local start = left()
            for _ = 1, 3 do
                M.tp(CFrame.new(e.pad.Position + Vector3.new(0, 4, 0)))
                local t0 = os.clock()
                repeat task.wait(0.05) until left() < start * 0.3 or os.clock() - t0 > 0.8
                if left() < start * 0.3 then break end
                M.tp(CFrame.new(e.pad.Position + Vector3.new(0, 4, 7)))
                task.wait(0.25)
            end
        end
    end)
    M.goHome()
    M.busy = false
    S.collects += 1
    LOG("collected", #list, M.fmt(M.cash() - c0))
    return true
end
function F.spend()
    local d = M.data()
    if not d then return end
    local cash = d.Cash or 0
    local budget = cash - M.keep()
    if on("f_arms") and D.Arms then
        local nextKey = D.AU and M.call(function() return D.AU.GetNextUnlockKey(d) end)
        local a = nextKey and D.Arms[nextKey]
        if a and a.UnlockCost and a.UnlockCost <= budget and not (d.PurchasedArms and d.PurchasedArms[nextKey]) then
            M.fire("ArmsAction", "Unlock", nextKey)
            task.wait(0.8)
            local d2 = M.data()
            if d2 and d2.PurchasedArms and d2.PurchasedArms[nextKey] then S.arms += 1 LOG("arm", nextKey) d = d2 budget = (d2.Cash or 0) - M.keep() end
        end
        local best, bp = nil, -1
        for key, owned in pairs(d.PurchasedArms or {}) do
            if owned == true then
                local pw = D.AU and M.call(function() return D.AU.GetMultiplier(d, key) end) or (D.Arms[key] and D.Arms[key].ArmPower) or 0
                if (tonumber(pw) or 0) > bp then best, bp = key, tonumber(pw) end
            end
        end
        if best and best ~= d.EquippedArmKey then M.fire("ArmsAction", "Equip", best) LOG("equip", best) return end
    end
    if on("f_ups") and D.Ups then
        local lvl = tonumber(d.Upgrades and d.Upgrades.Backpack) or 0
        local nx = D.Ups.Backpack and D.Ups.Backpack[lvl + 1]
        if nx and nx.Cost and nx.Cost <= budget then
            local ok = M.inv("PurchaseUpgrade", "Backpack")
            if ok then S.ups += 1 LOG("upgrade Backpack") return end
        end
    end
    if on("f_plot") and D.Plot and D.Plot.UPGRADE_PRICES then
        local lvl = tonumber(d.BaseLevel) or 0
        local price = D.Plot.UPGRADE_PRICES[lvl]
        local need = 0
        local plot = M.plot()
        if plot then
            local idx = (D.Plot.DefaultUnlockedSlots or 5) + lvl + 1
            local per = D.Plot.NumberStands or 10
            local fl = plot:FindFirstChild("Floor" .. math.ceil(idx / per))
            local sl = fl and fl:FindFirstChild("Slots") and fl.Slots:FindFirstChild("Slot" .. ((idx - 1) % per + 1))
            need = sl and tonumber(sl:GetAttribute("RequiredRebirths")) or 0
        end
        if price and lvl < (D.Plot.MaxLevel or 15) and price <= budget and (d.Rebirths or 0) >= need then
            M.fire("UpgradePlot") task.wait(0.8)
            local d2 = M.data()
            if d2 and (d2.BaseLevel or 0) > lvl then S.plots += 1 LOG("plot", lvl + 1) return end
        end
    end
    if on("f_rebirth") and D.Reb and D.Reb.Levels then
        local r = tonumber(d.Rebirths) or 0
        local lv = D.Reb.Levels[r + 1]
        if lv and lv.CashRequired and cash >= lv.CashRequired and M.keep() <= 0 then
            M.fire("PerformRebirth") task.wait(1)
            local d2 = M.data()
            if d2 and (d2.Rebirths or 0) > r then S.rebirths += 1 LOG("rebirth", r + 1) notify(__T["Rebirth "] .. (r + 1)) end
        end
    end
end
F.rewardAt = 0
function F.rewards()
    if not on("f_rewards") or os.clock() - F.rewardAt < 600 then return end
    F.rewardAt = os.clock()
    for i = 1, 7 do M.fire("ClaimReward", "Daily" .. i) end
    if (lp:GetAttribute("OfflineRewardCash") or 0) > 0 then M.fire("CollectOfflineRewards") LOG("offline") S.rewards += 1 end
    local d = M.data()
