function F.baseLoop()
    while RUNNING do
        pcall(F.collect)
        if not M.busy and os.clock() - F.manAt > 20 then M.busy = true pcall(F.afterBank) M.busy = false end
        pcall(F.spend)
        pcall(F.rewards)
        if not (D.Arms and D.Treas and D.DA) then pcall(M.loadData) end
        task.wait(2)
    end
end
function F.tpTargets() return { "Home", "Sell", "Arms", "Upgrades", "Highest Stage" } end
function F.tpTo(name)
    local target
    local shops = Workspace.Map:FindFirstChild("Shops")
    if name == "Home" then local h = M.home() if h then M.tp(h) end return end
    if name == "Highest Stage" then
        local hf = lp:GetAttribute("HighestFloor") or 1
        target = F.stageModel(math.max(1, hf)) target = target and target:FindFirstChild("Spawn", true)
    else target = shops and shops:FindFirstChild(name) end
    if not target then return end
    local ok, cf = pcall(function() return target:IsA("BasePart") and target.CFrame or target:GetPivot() end)
    if not ok then return end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { lp.Character }
    for _, off in ipairs({ Vector3.new(0, 0, 8), Vector3.new(8, 0, 0), Vector3.new(-8, 0, 0), Vector3.new(0, 0, -8), Vector3.new(0, 0, 0) }) do
        local hit = Workspace:Raycast(cf.Position + off + Vector3.new(0, 6, 0), Vector3.new(0, -30, 0), params)
        if hit and hit.Normal.Y > 0.6 and not Workspace:Raycast(hit.Position + Vector3.new(0, 3, 0), Vector3.new(0, 4, 0), params) then
            M.tp(CFrame.new(hit.Position + Vector3.new(0, 3, 0))) return
        end
    end
    M.tp(cf.Position + Vector3.new(0, 5, 0))
end
